#include <iostream>
#include <mutex>
#include <thread>

int main() {
    int counter = 0;
    std::mutex m;
    auto work = [&] {
        for (int i = 0; i < 1000; ++i) {
            std::lock_guard<std::mutex> lock(m);
            ++counter;
        }
    };
    std::thread a(work), b(work);
    a.join(); b.join();
    std::cout << counter << "\n";
    return 0;
}

