#include <vector>

int main() {
    std::vector<int> v{1, 2, 4, 7};
    int target = 9, i = 0, j = static_cast<int>(v.size()) - 1;
    bool found = false;
    while (i < j) {
        int sum = v[i] + v[j];
        if (sum == target) { found = true; break; }
        if (sum < target) ++i; else --j;
    }
    std::cout << found << "\n";
    return 0;
}

